def experiment(inputs):
    history = inputs.get('history', [])
    valid = 0
    for t in history:
        if isinstance(t, dict) and 'transition_id' in t and len(t['transition_id']) > 0:
            valid += 1
    return {"valid_count": valid, "total": len(history)}

